const examQ = (heading: string, body: string) => ({ heading, body, collapsible: true });

const examDay: Day = {
	n: 12,
	phaseId: 'exam',
	unitLabel: 'Экзамен',
	title: 'Вопросы к экзамену (17)',
	chapterRef: 'экзамен',
	est: '—',
	kind: 'theory',
	goal: String.raw`Полный разбор всех 17 теоретических вопросов экзамена по ЧМА: постановка, ключевые формулы и центральный вывод (доказательство) по каждому билету.`,
	sections: [
		examQ("Билет 1. Постановка задачи интерполяции и полином $Q_n$ Лагранжа", "## Постановка задачи\n\nФункция $f(x)$ задана таблично: в $n+1$ различных точках $x_0,x_1,\\dots,x_n$ (это [[uzel-interp|узлы]]) известны значения $f(x_0),\\dots,f(x_n)$. Между узлами $f$ может быть громоздкой или вовсе неизвестной. Требуется построить *удобную* замену $g(x)$ из заданного класса, **точно** проходящую через узлы:\n$$g(x_i)=f(x_i),\\qquad i=0,1,\\dots,n. \\tag{1}$$\nЭто и есть [[interpolyaciya|интерполяция]] (в отличие от [[mnk|МНК]], где приближение лишь близко к данным). Класс берём простейший — алгебраические полиномы степени не выше $n$. Вопрос: существует ли такой полином и единствен ли он.\n\n## Прямое решение через СЛАУ (Вандермонд)\n\nИщем $g(x)=\\sum_{j=0}^{n}a_jx^j$. Подставив условия $(1)$, получаем СЛАУ относительно коэффициентов $a_j$:\n$$\\begin{cases}a_0+a_1x_0+\\dots+a_nx_0^{\\,n}=f(x_0),\\\\ \\quad\\vdots\\\\ a_0+a_1x_n+\\dots+a_nx_n^{\\,n}=f(x_n).\\end{cases} \\tag{3}$$\nМатрица квадратная ($n+1$ уравнение и неизвестных), её определитель — [[vandermond|определитель Вандермонда]]\n$$\\det V=\\prod_{0\\le i<j\\le n}(x_j-x_i).$$\nПри **несовпадающих** узлах все разности $x_j-x_i\\neq0$, значит $\\det V\\neq0$, система $(3)$ невырождена — полином степени $n$ **существует и единствен**. Но решать СЛАУ Вандермонда невыгодно: матрица плохо [[chislo-obuslovlennosti|обусловлена]], стоимость $\\sim n^3$. Поэтому строят явную формулу.\n\n## Центральный вывод: множители и формула Лагранжа\n\nВведём узловой полином $\\omega(x)=\\prod_{i=0}^{n}(x-x_i)$ степени $n+1$ и «вырезанный»\n$$\\omega_k(x)=\\frac{\\omega(x)}{x-x_k}=\\prod_{i\\neq k}(x-x_i).$$\nВ чужом узле $x_i\\neq x_k$ одна скобка зануляется: $\\omega_k(x_i)=0$; в своём $\\omega_k(x_k)=\\prod_{i\\neq k}(x_k-x_i)\\neq0$. Нормируя, получаем [[mnozhitel-lagranzha|множители Лагранжа]]:\n$$l_k(x)=\\frac{\\omega_k(x)}{\\omega_k(x_k)}=\\frac{\\prod_{i\\neq k}(x-x_i)}{\\prod_{i\\neq k}(x_k-x_i)}. \\tag{5}$$\nКаждый $l_k$ — полином степени $n$ с **дельта-свойством**\n$$l_k(x_i)=\\delta_{ki}=\\begin{cases}1,& i=k,\\\\ 0,& i\\neq k.\\end{cases} \\tag{6}$$\nТогда [[polinom-lagranzha|полином Лагранжа]]\n$$Q_n(x)=\\sum_{k=0}^{n}l_k(x)\\,f(x_k) \\tag{7}$$\nимеет степень $\\le n$. **Проверка условий $(1)$:** подставим узел $x_i$ и применим $(6)$ — в сумме выживает лишь слагаемое $k=i$:\n$$Q_n(x_i)=\\sum_{k=0}^{n}l_k(x_i)f(x_k)=l_i(x_i)f(x_i)=1\\cdot f(x_i)=f(x_i).$$\nУсловия выполнены. По доказанной единственности этот $Q_n$ совпадает с решением СЛАУ $(3)$, но получен **без** её решения. $\\blacksquare$\n\n*Идея:* $l_k$ — «выключатель» $k$-го узла (горит в $x_k$, погашен в остальных); складывая «лампочки» $l_k\\cdot f(x_k)$, в каждом узле получаем ровно $f(x_i)$.\n\n## Точность, свойства, область применимости\n\n- **Контроль:** $\\sum_{k}l_k(x)\\equiv1$ (интерполяция $f\\equiv1$ даёт саму константу по единственности).\n- **Остаточный член** при $f\\in C^{n+1}[a,b]$:\n$$R_n(x)=f(x)-Q_n(x)=\\frac{f^{(n+1)}(\\eta)}{(n+1)!}\\,\\omega(x),\\quad \\eta\\in(a,b),$$\nпорядок ошибки задаётся узловым полиномом $\\omega(x)$.\n- **Применимость:** на равномерной сетке $\\max|\\omega|$ велик у краёв, при росте $n$ возможен [[fenomen-runge|феномен Рунге]] (расходимость для $1/(1+25x^2)$); лекарство — узлы [[polinom-chebysheva|Чебышёва]] или [[splajn|сплайны]].\n- **Недостаток Лагранжа:** при добавлении узла все $l_k$ пересчитываются; гибче [[forma-newtona|форма Ньютона]] через [[razdelennaya-raznost|разделённые разности]], дающая *тот же* полином.\n\nПодробный разбор и интерактивный код — [День 1](/aii/chma/4/day/1)."),
		examQ("Билет 2. Оценка остаточного члена интерполяции; полином Лагранжа в форме Ньютона", "## Постановка задачи\n\nНа отрезке $[a;b]$ функция $f$ приближается интерполяционным [[polinom-lagranzha|полиномом Лагранжа]] $Q_m(x)$ степени $m$ по $m+1$ узлам $x_0,\\dots,x_m$, причём $Q_m(x_i)=f(x_i)$. Требуется: (1) оценить [[ostatochnyy-chlen|остаточный член]] $R_m(x)=f(x)-Q_m(x)$, доказав точную формулу через теорему Ролля; (2) записать тот же полином в [[forma-newtona|форме Ньютона]] через [[razdelennaya-raznost|разделённые разности]].\n\n## Определения и формулы\n\n**Узловой полином** (множитель ошибки) — нормированный полином степени $m+1$:\n$$\\omega(x)=\\prod_{i=0}^{m}(x-x_i),\\qquad \\omega(x)=x^{m+1}+\\dots$$\n**Разделённая разность** порядка $k$ задаётся рекуррентно $f(x_0;\\dots;x_k)=\\dfrac{f(x_0;\\dots;x_{k-1})-f(x_1;\\dots;x_k)}{x_0-x_k}$ и симметрична по узлам.\n\n## Теорема об оценке остаточного члена\n\n**Теорема.** Если $f\\in C^{m+1}[a;b]$, то для любого $x\\in[a;b]$ найдётся $\\eta$ внутри наименьшего интервала, содержащего $x$ и все узлы, такая что $R_m(x)=\\dfrac{f^{(m+1)}(\\eta)}{(m+1)!}\\,\\omega(x)$.\n\n**Доказательство (вспомогательная $\\psi$ и лестница Ролля).** Зафиксируем $x\\ne x_i$ и введём\n$$\\psi(t)=f(t)-Q_m(t)-K\\,\\omega(t).$$\n*Шаг 1.* В узлах $Q_m(x_i)=f(x_i)$ и $\\omega(x_i)=0$, поэтому $\\psi(x_i)=0$, $i=0,\\dots,m$ — уже $m+1$ нуль.\n*Шаг 2.* Подберём $K$ так, чтобы $\\psi(x)=0$: $K=\\dfrac{f(x)-Q_m(x)}{\\omega(x)}=\\dfrac{R_m(x)}{\\omega(x)}$ (деление законно, $\\omega(x)\\ne0$). Теперь у $\\psi$ не менее $m+2$ нулей.\n*Шаг 3.* $\\psi\\in C^{m+1}$, и по теореме Ролля между соседними нулями лежит нуль производной:\n$$\\psi'\\!:\\ge m+1,\\quad \\psi''\\!:\\ge m,\\quad\\dots,\\quad \\psi^{(m+1)}\\!:\\ge 1\\text{ нуль}=\\eta.$$\n*Шаг 4.* Дифференцируем $m+1$ раз: $f^{(m+1)}$ остаётся; $Q_m^{(m+1)}\\equiv0$ (степень $m$); $\\omega^{(m+1)}=(m+1)!$ (старший член $t^{m+1}$). Значит\n$$\\psi^{(m+1)}(\\eta)=f^{(m+1)}(\\eta)-K\\,(m+1)!=0\\;\\Rightarrow\\;K=\\frac{f^{(m+1)}(\\eta)}{(m+1)!}.$$\n*Шаг 5.* Сравнивая с $K=R_m(x)/\\omega(x)$, получаем $R_m(x)=\\dfrac{f^{(m+1)}(\\eta)}{(m+1)!}\\,\\omega(x).\\;\\blacksquare$\n\n## Форма Ньютона\n\nРаскручиваем разность с текущей точкой $x$. Из $f(x;x_0)=\\dfrac{f(x)-f(x_0)}{x-x_0}$ следует $f(x)=f(x_0)+(x-x_0)f(x;x_0)$. Подставляя на общем шаге $f(x;x_0;\\dots;x_{k-1})=f(x_0;\\dots;x_k)+(x-x_k)f(x;x_0;\\dots;x_k)$, приходим к точному тождеству:\n$$Q_m(x)=f(x_0)+\\sum_{k=1}^{m}(x-x_0)(x-x_1)\\cdots(x-x_{k-1})\\,f(x_0;\\dots;x_k),$$\n$$R_m(x)=(x-x_0)\\cdots(x-x_m)\\,f(x;x_0;\\dots;x_m).$$\nТак как $f(x;x_0;\\dots;x_m)=\\dfrac{f^{(m+1)}(\\xi)}{(m+1)!}$, остаток Ньютона совпадает с формой Лагранжа. В силу единственности интерполяционного полинома обе формы задают **один и тот же** $Q_m$.\n\n## Оценки, ошибки и условия\n\nИз теоремы при $M_{m+1}\\ge\\max|f^{(m+1)}|$:\n$$|R_m(x)|\\le\\underbrace{\\frac{M_{m+1}}{(m+1)!}}_{\\text{свойство }f}\\cdot\\underbrace{|\\omega(x)|}_{\\text{свойство сетки}}.$$\n- **Условие:** $f\\in C^{m+1}[a;b]$ (нужно для $m{+}1$-кратного дифференцирования); узлы различны и лежат в $[a;b]$.\n- **Феномен Рунге:** рост степени не гарантирует $\\varepsilon\\to0$ — числитель $M_{m+1}$ может обгонять факториал; управляем лишь $|\\omega|$ выбором узлов.\n- **Преимущество Ньютона:** добавление узла $x_{m+1}$ дописывает ровно одно слагаемое $(x-x_0)\\cdots(x-x_m)f(x_0;\\dots;x_{m+1})$, старые разности не пересчитываются — в отличие от формы Лагранжа.\n\nПодробный разбор и интерактивный код — [День 2](/aii/chma/4/day/2) и [День 3](/aii/chma/4/day/3)."),
		examQ("Билет 3. Феномен Рунге, полиномы Чебышёва и минимизация остаточного члена", "## Постановка задачи\n\nФункция $f\\in C^{m+1}[a;b]$ приближается [[polinom-lagranzha|интерполяционным полиномом Лагранжа]] $Q_m$ степени $m$ по $m+1$ узлам $x_0,\\dots,x_m$, причём $Q_m(x_i)=f(x_i)$. [[ostatochnyy-chlen|Остаточный член]] $R_m(x)=f(x)-Q_m(x)$ в узлах нулевой; интересна его величина вне узлов. **Цель:** вывести точную форму $R_m$, понять [[fenomen-runge|феномен Рунге]] (почему рост степени $m$ не уменьшает ошибку) и так расставить узлы, чтобы минимизировать ошибку, — для этого служат [[polinom-chebysheva|полиномы Чебышёва]].\n\n## Определения и формулы\n\n**Узловой полином** $\\omega(x)=\\prod_{i=0}^{m}(x-x_i)$ — нормированный ($\\omega(x)=x^{m+1}+\\dots$) полином степени $m+1$.\n**Полиномы Чебышёва:** $T_0\\equiv1$, $T_1=x$, $T_m=2x\\,T_{m-1}-T_{m-2}$; на $[-1;1]$ имеем $T_m(x)=\\cos(m\\arccos x)$, откуда $|T_m|\\le1$, старший коэффициент $2^{m-1}$, экстремумы $\\tilde x_j=\\cos\\frac{\\pi j}{m}$ с $T_m(\\tilde x_j)=(-1)^j$. **Нормировка:** $\\bar T_m=2^{1-m}T_m=x^m+\\dots$, $\\|\\bar T_m\\|_{C[-1;1]}=2^{1-m}$.\n\n## Центральный вывод 1: форма остаточного члена\n\nЗафиксируем $x\\ne x_i$ и введём $\\psi(t)=f(t)-Q_m(t)-K\\,\\omega(t)$.\n**Шаг 1.** В узлах $Q_m(x_i)=f(x_i)$, $\\omega(x_i)=0$, значит $\\psi(x_i)=0$ — это $m+1$ нуль.\n**Шаг 2.** Подберём $K$ так, чтобы $\\psi(x)=0$: $K=\\dfrac{R_m(x)}{\\omega(x)}$ (законно, $\\omega(x)\\ne0$). Теперь нулей $\\ge m+2$.\n**Шаг 3 (лестница Ролля).** Между соседними нулями $\\psi$ лежит нуль $\\psi'$; повторяя:\n$$\\psi'\\!:\\ge m{+}1,\\;\\;\\psi''\\!:\\ge m,\\;\\dots,\\;\\psi^{(m+1)}\\!:\\ge1\\text{ нуль}\\;\\Rightarrow\\;\\exists\\,\\eta:\\ \\psi^{(m+1)}(\\eta)=0.$$\n**Шаг 4.** Дифференцируем: $f^{(m+1)}$, $Q_m^{(m+1)}\\equiv0$ (степень $m$), $\\omega^{(m+1)}=(m+1)!$. Тогда\n$$\\psi^{(m+1)}(\\eta)=f^{(m+1)}(\\eta)-K\\,(m+1)!=0\\;\\Rightarrow\\;K=\\frac{f^{(m+1)}(\\eta)}{(m+1)!}.$$\n**Шаг 5.** Сравнивая с шагом 2:\n$$\\boxed{\\,R_m(x)=\\frac{f^{(m+1)}(\\eta)}{(m+1)!}\\,\\omega(x)\\,},\\qquad\\eta=\\eta(x)\\in(a;b).$$\n\n## Центральный вывод 2: лемма о минимизации $\\max|\\omega|$\n\n**Среди всех нормированных $\\bar P_m$ наименее уклоняется от нуля на $[-1;1]$ именно $\\bar T_m$:** $\\|\\bar P_m\\|\\ge2^{1-m}$.\n*От противного.* Пусть $\\|\\bar P_m\\|<2^{1-m}$. Разность $S_{m-1}=\\bar T_m-\\bar P_m$: старшие члены $x^m$ сокращаются, степень $\\le m-1$, корней $\\le m-1$. В $m+1$ точке экстремума $\\tilde x_j$ имеем $|\\bar T_m(\\tilde x_j)|=2^{1-m}>|\\bar P_m(\\tilde x_j)|$, поэтому знак разности задаёт $\\bar T_m$:\n$$\\operatorname{sign}S_{m-1}(\\tilde x_j)=(-1)^j,\\qquad j=0,\\dots,m.$$\nЧередование знаков в $m+1$ точке даёт $\\ge m$ корней — невозможно для степени $\\le m-1$. Значит $\\|\\bar T_m\\|$ минимальна. $\\blacksquare$\n\n**Применение.** $\\omega$ имеет степень $m+1$; берём $m+1$ узлов как корни $T_{m+1}$, тогда $\\omega\\equiv\\bar T_{m+1}$, $\\|\\omega\\|=2^{-m}$ — наименьшее.\n\n## Обобщение на $[a;b]$ и условия\n\nЗамена $t=\\frac{2x-(a+b)}{b-a}$ даёт оптимальные узлы и оценку:\n$$x_i=\\frac{a+b}{2}+\\frac{b-a}{2}\\cos\\frac{\\pi(2i-1)}{2(m+1)},\\quad \\varepsilon\\le\\frac{2^{-2m}(b-a)^{m+1}}{(m+1)!}\\,\\bigl\\|f^{(m+1)}\\bigr\\|_{C[a;b]}.$$\n\n- **Два множителя:** $\\frac{M_{m+1}}{(m+1)!}$ (свойство $f$, не управляем) и $|\\omega|$ (свойство сетки, управляем).\n- **Феномен Рунге:** для $f=\\frac1{1+25x^2}$ числитель $M_{m+1}$ обгоняет $(m+1)!$, на равномерной сетке $|\\omega|$ растёт у концов — осцилляции у $\\pm1$. Чебышёвские узлы **сгущаются к концам** и лечат это.\n- **Условия:** нужна гладкость $f\\in C^{m+1}$. **NB:** лемма минимизирует $\\max|\\omega|$, а не $\\max|R_m|$ поточечно. На практике вместо роста $m$ дробят отрезок ([[splajn|сплайны]], [[sostavnaya-formula|составные формулы]]).\n\nПодробный разбор и интерактивный код — [День 2](/aii/chma/4/day/2)."),
		examQ("Билет 4. Разностные приближения производных через дифференцирование интерполяционного полинома", "## Постановка задачи\n\nДано: функция $f$, заданная значениями в узлах сетки $x_0,\\dots,x_n$ (далее — равноотстоящих с шагом $h=x_{i+1}-x_i$). Требуется приближённо вычислить $f'(x)$, $f''(x)$ в узловых точках и оценить погрешность приближения. Идея метода: заменить $f$ её [[interpolyaciya|интерполяционным полиномом]] $Q_m(x)$ и продифференцировать именно полином.\n\n## Ключевые определения и формулы\n\nПо построению интерполяции справедливо **точное** разложение $f(x)=Q_m(x)+R_m(x)$, где $R_m$ — [[ostatochnyy-chlen|остаточный член]]. Дифференцируя, получаем\n\n$$\\frac{d}{dx}f(x)=\\frac{d}{dx}Q_m(x)+\\frac{d}{dx}R_m(x).$$\n\n**Определение.** Формула численного дифференцирования: $\\frac{d}{dx}f(x)\\approx\\frac{d}{dx}Q_m(x)$, а её **погрешность** есть $\\varepsilon=\\frac{d}{dx}R_m(x)$. Любая [[raznostnoe-pribl|разностная производная]] — это производная подходящего $Q_m$, а её ошибка — производная остатка.\n\n## Центральный вывод: правая разность и её ошибка\n\nСтроим линейный интерполянт по узлам $x_i,x_{i+1}$ (форма Лагранжа):\n\n$$Q_1(x)=\\frac{x-x_{i+1}}{x_i-x_{i+1}}f(x_i)+\\frac{x-x_i}{x_{i+1}-x_i}f(x_{i+1}).$$\n\n**Шаг 1.** Знаменатели — константы, производные числителей равны $1$:\n\n$$\\frac{d}{dx}Q_1(x)=\\frac{f(x_{i+1})-f(x_i)}{x_{i+1}-x_i}=\\frac{f(x_{i+1})-f(x_i)}{h}.$$\n\n**Шаг 2.** Остаток линейной интерполяции (через теорему Ролля для функции с тремя нулями):\n\n$$R_1(x)=\\frac{f''(\\eta)}{2!}(x-x_i)(x-x_{i+1}),\\qquad \\eta\\in[a;b].$$\n\n**Шаг 3.** Дифференцируем по правилу произведения, обозначив $g(x)=(x-x_i)(x-x_{i+1})$:\n\n$$\\varepsilon=\\Big(\\tfrac{f''(\\eta)}{2!}\\Big)' g(x)+\\frac{f''(\\eta)}{2!}\\big(2x-x_i-x_{i+1}\\big).$$\n\n**Шаг 4.** Подставляем точку оценки $x=x_i$. Множитель $(x-x_i)=0$ обнуляет первое (неприятное) слагаемое с производной от $f''(\\eta)$:\n\n$$\\varepsilon\\big|_{x=x_i}=\\frac{f''(\\eta)}{2}(2x_i-x_i-x_{i+1})=\\frac{f''(\\eta)}{2}(x_i-x_{i+1})=-\\frac{f''(\\eta)}{2}h.\\qquad\\blacksquare$$\n\nДля левой разности с узлами $x_{i-1},x_i$ знак меняется: $\\varepsilon=+\\frac{f''(\\eta)}{2}h$.\n\n## Центральная разность и повышение порядка\n\nПо трём узлам в точке $x_i$: $\\dfrac{d}{dx}Q_2|_{x_i}=\\dfrac{f(x_{i+1})-f(x_{i-1})}{2h}$. Чище всего порядок виден из ряда Тейлора — вычитая разложения, **чётные** степени сокращаются:\n\n$$f(x_{i+1})-f(x_{i-1})=2hf'(x_i)+\\tfrac{h^3}{3}f'''(x_i)+\\dots\\;\\Rightarrow\\;\\frac{f(x_{i+1})-f(x_{i-1})}{2h}=f'(x_i)+\\frac{h^2}{6}f'''(x_i)+\\dots$$\n\nто есть $\\varepsilon=-\\frac{f'''(\\eta)}{6}h^2=O(h^2)$. Аналогично сложение даёт вторую разность $\\frac{f_{i-1}-2f_i+f_{i+1}}{h^2}=f''(x_i)+\\frac{h^2}{12}f^{(4)}+\\dots$, с оценкой $\\varepsilon=-\\frac{f^{(4)}(\\eta)}{3}h^2$.\n\n## Ошибки, порядок точности, область применимости\n\n- **Односторонние** (левая/правая) — порядок $O(h)$, ошибка $\\sim f''$; **центральные** — $O(h^2)$, ошибка $\\sim f'''$ (или $f^{(4)}$). Симметрия сокращает чётные члены Тейлора — отсюда выигрыш на порядок.\n- **Условие:** нужна гладкость $f$ до порядка, на единицу выше порядка формулы.\n- **Неустойчивость при малом $h$.** В числителе — разность близких чисел; при ошибке записи $\\epsilon$ полная погрешность $\\bar\\varepsilon\\le\\frac{M^{(2)}}{2}h+\\frac{2\\epsilon}{h}$ имеет U-образный вид. Минимизация даёт $h_{\\text{опт}}=2\\sqrt{\\epsilon/M^{(2)}}$, минимум $\\sim O(\\sqrt\\epsilon)$; для центральной $h_{\\text{опт}}\\sim\\epsilon^{1/3}$, минимум $O(\\epsilon^{2/3})$. Чрезмерное измельчение сетки **портит** ответ.\n\nПодробный разбор и интерактивный код — [День 4](/aii/chma/4/day/4)."),
		examQ("Билет 5. Элементарные квадратурные формулы из интегрирования полиномов и их ошибки", "## Постановка задачи\n\nДано: гладкая на $[a;b]$ функция $f$, требуется приближённо вычислить $I=\\int_a^b f(x)\\,dx$, который аналитически взять не умеем. **Идея:** заменить $f$ её [[polinom-lagranzha|интерполяционным полиномом]] $Q_m$ по узлам $x_0,\\dots,x_m\\in[a;b]$ и проинтегрировать полином точно. Поскольку $f(x)=Q_m(x)+R_m(x)$ тождественно ($R_m$ — [[ostatochnyy-chlen|остаточный член]] интерполяции),\n$$I=\\int_a^b Q_m\\,dx+\\int_a^b R_m\\,dx,\\qquad \\varepsilon=\\int_a^b R_m(x)\\,dx.$$\nИщем сами формулы (веса) и оценки ошибки $\\varepsilon$.\n\n## Ключевые определения и формулы\n\n[[kvadraturnaya-formula|Квадратурная формула]] — приближённое равенство $\\int_a^b f\\,dx\\approx\\sum_{k=0}^m A_k f(x_k)$, где узлы $x_k$ и веса $A_k$ не зависят от $f$. Подставив форму Лагранжа $Q_m=\\sum_k f(x_k)\\,l_k(x)$ с базисными $l_k(x)=\\prod_{j\\ne k}\\frac{x-x_j}{x_k-x_j}$ и вынеся $f(x_k)$, получаем вес как интеграл базисного многочлена:\n$$A_k=\\int_a^b l_k(x)\\,dx.$$\nФормула с $m+1$ узлом точна для всех полиномов степени $\\le m$ (для них $R_m\\equiv0$). Простейшие случаи дают [[formula-trapecij|формулу трапеций]] ($Q_1$ по $a,b$) и [[formula-simpsona|формулу Симпсона]] ($Q_2$ по $a,\\frac{a+b}{2},b$).\n\n## Центральный вывод: остаточные члены\n\nБазовый инструмент — **теорема о среднем для знакопостоянного веса**: если $\\varphi_2$ не меняет знак на $[a;b]$, то $\\int_a^b\\varphi_1\\varphi_2\\,dx=\\varphi_1(\\eta^*)\\int_a^b\\varphi_2\\,dx$, $\\eta^*\\in[a;b]$.\n\n**Трапеции.** Остаток интерполяции по двум узлам: $R_1(x)=\\frac{f''(\\eta(x))}{2!}(x-a)(x-b)$. Множитель $(x-a)(x-b)\\le0$ знакопостоянен, поэтому\n$$\\varepsilon_\\text{т}=\\int_a^b\\frac{f''(\\eta(x))}{2}(x-a)(x-b)\\,dx=\\frac{f''(\\eta^*)}{2}\\int_a^b(x-a)(x-b)\\,dx.$$\nПодстановкой $x=a+t$, $\\ell=b-a$: $\\int_0^\\ell t(t-\\ell)\\,dt=\\frac{\\ell^3}{3}-\\frac{\\ell^3}{2}=-\\frac{\\ell^3}{6}$, откуда\n$$\\varepsilon_\\text{т}=-\\frac{(b-a)^3}{12}\\,f''(\\eta^*).$$\n\n**Симпсон.** Прямой путь не работает: $(x-a)(x-c)(x-b)$ нечётен относительно $c=\\frac{a+b}{2}$, меняет знак, и его интеграл равен нулю — главный член ошибки прячется в следующий порядок. Идём методом неопределённого коэффициента. Формула точна на $1,x,x^2$ (интеграл параболы), а проверка на $[-1;1]$ даёт $\\frac{2}{6}((-1)^3+0+1^3)=0=\\int_{-1}^1 x^3\\,dx$ — точна и для $x^3$. Значит $\\varepsilon_\\text{C}=K f^{(4)}(\\eta^*)$. Подставляя $f=x^4$ на $[-1;1]$ ($f^{(4)}\\equiv24$):\n$$\\int_{-1}^1 x^4\\,dx=\\tfrac{2}{5},\\quad I_\\text{C}=\\tfrac{2}{6}\\cdot2=\\tfrac{2}{3},\\quad \\varepsilon_\\text{C}=\\tfrac{2}{5}-\\tfrac{2}{3}=-\\tfrac{4}{15}=K\\cdot24\\ \\Rightarrow\\ K=-\\tfrac{1}{90}.$$\nПересчёт к общей длине через $(b-a)^5$ даёт\n$$\\varepsilon_\\text{C}=-\\frac{(b-a)^5}{2880}\\,f^{(4)}(\\eta^*).\\qquad\\blacksquare$$\n\n## Ошибки, порядок точности, условия\n\n- Степень $(b-a)$ в остатке на единицу выше алгебраического порядка. Трапеция точна для линейных функций (остаток через $f''$), Симпсон — для **кубических** (через $f^{(4)}$): «лишний» порядок даёт симметрия — антисимметричная добавка $(x-c)^3$ гасится на симметричном отрезке.\n- Для справки: левые/правые прямоугольники $\\varepsilon=\\pm\\frac{(b-a)^2}{2}f'(\\eta^*)$, средние $\\frac{(b-a)^3}{24}f''(\\eta^*)$.\n- В составных формулах через дискретную теорему о среднем: трапеция $\\varepsilon_\\text{т}=-\\frac{b-a}{12}h^2 f''(\\eta^*)=O(h^2)$, Симпсон $=O(h^4)$; удвоение $N$ снижает ошибку в 4 и 16 раз.\n- **Условия:** существование $f''$ (трапеция) и $f^{(4)}$ (Симпсон); при изломе порядок падает. Знак ошибки трапеции совпадает со знаком $f''$ (на выпуклой завышает).\n\nПодробный разбор и интерактивный код — [День 5](/aii/chma/4/day/5)."),
		examQ("Билет 6. Интегрирование интерполяционных полиномов; составные [[sostavnaya-formula|квадратурные формулы]] и их ошибки", "## Постановка задачи\n\nДан определённый интеграл $I=\\int_a^b f(x)\\,dx$ от достаточно гладкой $f$, который не берётся в элементарных функциях. Требуется приближённо вычислить $I$, заменив $f$ интерполяционным полиномом, получить элементарные [[kvadraturnaya-formula|квадратурные формулы]] (трапеций, Симпсона) с остаточными членами, перейти к [[sostavnaya-formula|составным формулам]] и доказать их порядки точности $O(h^2)$ и $O(h^4)$.\n\n## Ключевые определения и формулы\n\nЗаменим $f$ её [[polinom-lagranzha|полиномом Лагранжа]] $Q_m(x)=\\sum_{k=0}^m f(x_k)\\,l_k(x)$ по узлам $x_0,\\dots,x_m\\in[a;b]$. Тогда $f=Q_m+R_m$, где $R_m$ — [[ostatochnyy-chlen|остаточный член]]. Интегрируя и вынося $f(x_k)$, получаем **квадратурную формулу**\n$$\\int_a^b f(x)\\,dx\\approx\\sum_{k=0}^{m}A_k\\,f(x_k),\\qquad A_k=\\int_a^b l_k(x)\\,dx.$$\nВеса $A_k$ зависят только от узлов; формула с $m+1$ узлом точна для всех полиномов степени $\\le m$. Элементарные [[formula-trapecij|трапеция]] и [[formula-simpsona|Симпсон]]:\n$$I_\\text{т}=(b-a)\\tfrac{f(a)+f(b)}{2},\\quad \\varepsilon_\\text{т}=-\\tfrac{(b-a)^3}{12}f''(\\eta^*);$$\n$$I_\\text{C}=\\tfrac{b-a}{6}\\big(f(a)+4f(\\tfrac{a+b}{2})+f(b)\\big),\\quad \\varepsilon_\\text{C}=-\\tfrac{(b-a)^5}{2880}f^{(4)}(\\eta^*).$$\n\n## Центральный вывод: остаток трапеций и порядки составных формул\n\n**Остаток трапеций.** Остаток интерполяции по узлам $a,b$: $R_1(x)=\\tfrac{f''(\\eta(x))}{2}(x-a)(x-b)$. Множитель $(x-a)(x-b)\\le0$ знакопостоянен на $[a;b]$, поэтому по теореме о среднем для знакопостоянного веса\n$$\\varepsilon_\\text{т}=\\int_a^b\\frac{f''(\\eta(x))}{2}(x-a)(x-b)\\,dx=\\frac{f''(\\eta^*)}{2}\\int_a^b(x-a)(x-b)\\,dx.$$\nПодстановкой $x=a+t,\\ \\ell=b-a$: $\\int_0^{\\ell}t(t-\\ell)\\,dt=\\tfrac{\\ell^3}{3}-\\tfrac{\\ell^3}{2}=-\\tfrac{\\ell^3}{6}$, откуда\n$$\\varepsilon_\\text{т}=\\frac{f''(\\eta^*)}{2}\\cdot\\!\\left(-\\frac{\\ell^3}{6}\\right)=-\\frac{(b-a)^3}{12}\\,f''(\\eta^*).$$\n\n**Составные формулы.** Разобьём $[a;b]$ сеткой $h=\\tfrac{b-a}{N}$, $x_i=a+ih$, и сложим элементарные. Внутренние узлы учитываются дважды:\n$$I_\\text{т}=\\frac{h}{2}\\Big(f(a)+2\\!\\sum_{i=1}^{N-1}f(x_i)+f(b)\\Big),\\quad I_\\text{C}=\\frac{h}{3}\\Big(f(a)+4\\!\\!\\sum_{\\text{неч.}}\\!\\!f(x_i)+2\\!\\!\\sum_{\\text{чёт.}}\\!\\!f(x_i)+f(b)\\Big).$$\n\n**Порядки через дискретную теорему о среднем** ($\\sum_i f^{(k)}(\\eta_i)=N f^{(k)}(\\eta^*)$). Трапеция: суммируя $N$ ошибок $-\\tfrac{h^3}{12}f''(\\eta_i)$ и используя $Nh^3=(b-a)h^2$,\n$$\\varepsilon_\\text{т}=-\\frac{Nh^3}{12}f''(\\eta^*)=-\\frac{b-a}{12}\\,h^2\\,f''(\\eta^*)=O(h^2).$$\nСимпсон: на сдвоенном шаге $2h$ ошибка $-\\tfrac{(2h)^5}{2880}f^{(4)}=-\\tfrac{h^5}{90}f^{(4)}$, троек $N/2$, и $Nh^5=(b-a)h^4$:\n$$\\varepsilon_\\text{C}=-\\frac{Nh^5}{180}f^{(4)}(\\eta^*)=-\\frac{(b-a)^5}{2880\\,N^4}f^{(4)}(\\eta^*)=O(h^4).\\ \\blacksquare$$\n\nСимпсон точен и для кубик (поправка $(x-c)^3$ антисимметрична относительно центра и при интегрировании гасится), поэтому ошибка содержит $f^{(4)}$, а не $f'''$, — «бесплатный» лишний порядок.\n\n## Ошибки, порядок и условия применимости\n\n- **Гладкость.** $O(h^2)$ требует $f''$, $O(h^4)$ — $f^{(4)}$. При изломе наблюдаемый наклон $\\ln\\varepsilon(\\ln N)$ положе $-2$ или $-4$.\n- **Дробление шага.** Удвоение $N$ уменьшает ошибку трапеции в $4$ раза, Симпсона — в $16$.\n- **Чётность $N$** обязательна для Симпсона (узлы клеятся тройками).\n- **Знак.** При $f''>0$ (выпуклость) $\\varepsilon_\\text{т}>0$: хорды над графиком, трапеция завышает.\n- **Предел.** Слишком малый $h$ выводит вперёд ошибку округления — суммарная погрешность снова растёт.\n\nПодробный разбор и интерактивный код — [День 5](/aii/chma/4/day/5)."),
		examQ("Билет 7. Кубический интерполяционный $[[splajn|сплайн]]$ дефекта 1", "## Постановка задачи\n\nНа отрезке $[a;b]$ задана сетка $a=x_1<x_2<\\dots<x_{N+1}=b$ ($N$ отрезков, $N+1$ узлов) и значения $f_k=f(x_k)$. **Задача интерполирования** — построить функцию $S$, проходящую через все узлы ($S(x_k)=f_k$) и приближающую $f$ между ними. Глобальный полином высокой степени даёт [[fenomen-runge|осцилляции у краёв]], поэтому строим **[[splajn|кубический сплайн дефекта 1]]**: на каждом $[x_k;x_{k+1}]$ — свой кубический многочлен $S_k$, а сама $S$ принадлежит классу $C^2$ (гладкость $C^{m-1}=C^2$ на единицу ниже степени $m=3$ — отсюда «дефект 1»).\n\n## Подсчёт условий и ключевые формулы\n\nКубики дают $4N$ неизвестных. Интерполяция даёт $N+1$ условие, непрерывность $S,S',S''$ во внутренних узлах — ещё $3(N-1)$. Итого $4N-2$ условия, остаются **2 степени свободы**, закрываемые граничными условиями.\n\nПараметризуем через **моменты** $\\sigma_k$, где $\\sigma_k=\\tfrac16 S''(x_k)$. Пусть $h_k=x_{k+1}-x_k$, $w_k=\\dfrac{x-x_k}{h_k}$, $\\bar w_k=1-w_k$. Полагаем\n$$S_k=w_k f_{k+1}+\\bar w_k f_k+h_k^2\\big[(w_k^3-w_k)\\sigma_{k+1}+(\\bar w_k^3-\\bar w_k)\\sigma_k\\big].$$\nЭта форма *автоматически* даёт $S_k(x_k)=f_k$, $S_k(x_{k+1})=f_{k+1}$ (интерполяция и непрерывность $S$).\n\n## Центральный вывод: трёхдиагональная СЛАУ на моменты\n\nДважды дифференцируя по $x$ (учитывая $w_k'=1/h_k$, $\\bar w_k'=-1/h_k$):\n$$S_k''=6w_k\\sigma_{k+1}+6\\bar w_k\\sigma_k,\\qquad S_k''(x_k)=6\\sigma_k,\\ \\ S_k''(x_{k+1})=6\\sigma_{k+1},$$\nто есть **непрерывность $S''$ выполнена тождественно**. Остаётся сшить $S'$. Дифференцируя $S_k$ один раз, в правом конце отрезка:\n$$S_k'(x_{k+1})=\\frac{f_{k+1}-f_k}{h_k}+\\sigma_k h_k+2\\sigma_{k+1}h_k,$$\nа слева в том же узле из соседнего отрезка:\n$$S_{k+1}'(x_{k+1})=\\frac{f_{k+2}-f_{k+1}}{h_{k+1}}-2\\sigma_{k+1}h_{k+1}-\\sigma_{k+2}h_{k+1}.$$\nПриравнивая $S_k'(x_{k+1})=S_{k+1}'(x_{k+1})$ и собирая моменты, получаем для $k=1,\\dots,N-1$:\n$$h_k\\,\\sigma_k+2(h_k+h_{k+1})\\,\\sigma_{k+1}+h_{k+1}\\,\\sigma_{k+2}=\\frac{f_{k+2}-f_{k+1}}{h_{k+1}}-\\frac{f_{k+1}-f_k}{h_k}.$$\nЭто $N-1$ уравнений на $N+1$ момент. Матрица **диагонально доминантна** ($2(h_k+h_{k+1})>h_k+h_{k+1}$), значит невырождена; система решается прогонкой за $O(N)$.\n\n## Виды граничных условий\n\nДве недостающие строки задают на концах:\n- **Естественный сплайн:** $S''(x_1)=S''(x_{N+1})=0$, то есть $\\sigma_1=\\sigma_{N+1}=0$. Минимизирует энергию изгиба $\\int (S'')^2dx$.\n- **Зажатый (клампированный):** заданы $S'(x_1)=f'(a)$, $S'(x_{N+1})=f'(b)$ — даёт две дополнительные строки на $\\sigma$ из условий на первую производную.\n- **Периодический:** $S'(a)=S'(b)$, $S''(a)=S''(b)$ (для периодической $f$).\n- **«Not-a-knot»:** непрерывность $S'''$ в $x_2$ и $x_N$ (третий узел не является «изломом»).\n\n## Ошибка приближения\n\nОстаточный член ведёт себя как у интерполяции степени 3:\n$$R_3(x)=\\frac{f^{(4)}(\\eta)}{4!}\\,\\omega(x),\\qquad \\bar\\varepsilon\\le C_{(4)}\\,h_{\\max}^4,\\quad C_{(4)}\\sim\\max|f^{(4)}|.$$\nТо есть на внутренней части порядок точности $O(h_{\\max}^4)$ для гладкой $f$. Для **естественного** сплайна вблизи концов точность падает до $O(h_{\\max}^3)$: условие $S''=0$ не согласовано с истинной $f''(a)$. Зажатый сплайн сохраняет $O(h^4)$ всюду, если $f'$ на концах задана точно.\n\nПодробный разбор и интерактивный код — [День 6](/aii/chma/4/day/6)."),
		examQ("Билет 8. Задача интерполирования, МНК и нормальные уравнения", "## Постановка задачи\n\nДан объект приближения $f$ — функция $f(x)$ на $[a;b]$ или вектор данных $f\\in\\mathbb R^n$ (узлы $x_i$, значения $f_i$, возможно зашумлённые). Фиксируем набор *линейно независимых* базисных функций $\\varphi_0,\\dots,\\varphi_m$ и ищем приближение в их линейной оболочке $L=\\operatorname{span}\\{\\varphi_j\\}$:\n$$g=\\sum_{j=0}^{m}a_j\\varphi_j,\\qquad g\\in L.$$\n\nЕсли требовать совпадения в узлах, $g(x_i)=f_i$ при $m=n-1$, — это **[[interpolyaciya|интерполирование]]** (точное прохождение через точки). Если точек больше параметров ($n>m+1$) или данные с шумом, точного совпадения не добиваются, а ставят задачу **[[nailuchshee-pribl|наилучшего приближения]]**: найти $g^*$, минимизирующий норму невязки $\\rho=\\lVert f-g\\rVert\\to\\min$. В случае квадратичной (евклидовой) нормы это **[[mnk|метод наименьших квадратов]]**.\n\n## Ключевые определения и формулы\n\nВ гильбертовом пространстве со скалярным произведением $\\langle\\cdot,\\cdot\\rangle$ и нормой $\\lVert u\\rVert_2=\\sqrt{\\langle u,u\\rangle}$ минимизируем\n$$\\rho^2=\\Big\\langle f-\\sum_j a_j\\varphi_j,\\ f-\\sum_j a_j\\varphi_j\\Big\\rangle\\to\\min_a.$$\nРабочие скалярные произведения — непрерывное $\\langle y_1,y_2\\rangle=\\int_a^b p\\,y_1 y_2\\,dx$ (вес $p>0$) и дискретное $\\langle y_1,y_2\\rangle=\\sum_i w_i\\,y_{1,i}y_{2,i}$.\n\n## Центральный вывод: нормальные уравнения из условия $f-g^*\\perp L$\n\n$\\rho^2(a)$ — выпуклая квадратичная форма (матрица Грама неотрицательна), поэтому минимум достигается в стационарной точке. Дифференцируем по $a_j$, пользуясь $\\partial_{a_j}\\big(f-\\sum_i a_i\\varphi_i\\big)=-\\varphi_j$ и билинейностью:\n$$\\frac{\\partial\\rho^2}{\\partial a_j}=2\\Big\\langle-\\varphi_j,\\ f-\\sum_i a_i\\varphi_i\\Big\\rangle=-2\\Big\\langle\\varphi_j,\\ f-\\sum_i a_i\\varphi_i\\Big\\rangle.$$\nПриравняв к нулю для всех $j=0,\\dots,m$:\n$$\\Big\\langle\\varphi_j,\\ f-\\sum_{i=0}^{m}a_i\\varphi_i\\Big\\rangle=0\\quad\\Longleftrightarrow\\quad f-g^*\\perp L.$$\nЭто геометрическое условие: невязка ортогональна всему подпространству $L$. Раскрывая, получаем **систему нормальных уравнений**\n$$\\sum_{i=0}^{m}\\langle\\varphi_j,\\varphi_i\\rangle\\,a_i=\\langle\\varphi_j,f\\rangle,\\quad j=0,\\dots,m,$$\nто есть $\\Gamma a=b$ с матрицей Грама $\\Gamma_{ji}=\\langle\\varphi_j,\\varphi_i\\rangle$. В дискретной матричной форме с матрицей плана $G=(\\varphi_i(x_k))$:\n$$G^{\\mathsf T}WG\\,a=G^{\\mathsf T}Wf\\ \\Longrightarrow\\ a=(G^{\\mathsf T}WG)^{-1}G^{\\mathsf T}Wf,$$\nпри $W=I$ — классический МНК $G^{\\mathsf T}G\\,a=G^{\\mathsf T}f$.\n\n**Почему это минимум (Пифагор).** Для любого $g=g^*+u$, $u\\in L$:\n$$\\lVert f-g\\rVert_2^2=\\lVert f-g^*\\rVert_2^2-2\\langle f-g^*,u\\rangle+\\lVert u\\rVert_2^2=\\lVert f-g^*\\rVert_2^2+\\lVert u\\rVert_2^2\\ge\\lVert f-g^*\\rVert_2^2,$$\nтак как средний член зануляется по ортогональности. Минимум — опускание перпендикуляра из $f$ на $L$.\n\n## Условия, единственность, обусловленность\n\n- **Существование и единственность.** Для любого $v$: $v^{\\mathsf T}G^{\\mathsf T}Gv=\\lVert Gv\\rVert_2^2\\ge0$, то есть $\\Gamma\\succeq0$. При линейно независимых $\\varphi_j$ имеем $Gv=0\\Rightarrow v=0$, значит $\\Gamma\\succ0$ и обратима — решение единственно. В общем (не евклидовом) нормированном пространстве минимум существует, но может быть не единственным.\n- **Ортогональный базис.** Если $\\langle\\varphi_i,\\varphi_j\\rangle=0$ при $i\\ne j$, $\\Gamma$ диагональна, $a_j=\\langle\\varphi_j,f\\rangle/\\langle\\varphi_j,\\varphi_j\\rangle$ независимо. Отсюда удобство [[polinom-chebysheva|полиномов Чебышёва]] и Лежандра.\n- **Обусловленность.** Для базиса $\\{1,x,\\dots,x^m\\}$ матрица $G^{\\mathsf T}G$ почти Вандермондова, [[chislo-obuslovlennosti|число обусловленности]] растёт катастрофически ($\\sim10^{18}$ при $m=18$). Лекарство — ортогональный базис либо QR/SVD без явного $G^{\\mathsf T}G$.\n\nПодробный разбор и интерактивный код — [День 6](/aii/chma/4/day/6)."),
		examQ("Билет 9. Нормы векторов и матриц; нормы Гёльдера; согласованность и подчинённость", "## Постановка задачи\n\nДано пространство $V^m$ и квадратные матрицы. Нужно: ввести аксиомы [[norma-vektora|векторной нормы]], построить семейство [[norma-geldera|норм Гёльдера]] и вывести предельный случай $p\\to\\infty$, сформулировать аксиомы [[norma-matricy|матричной нормы]] (с субмультипликативностью) и строго различить **согласованность** $\\|Ax\\|\\le\\|A\\|\\,\\|x\\|$ и **подчинённость** $\\|A\\|=\\sup_{x\\ne0}\\|Ax\\|/\\|x\\|$.\n\n## Ключевые определения\n\n**Векторная норма** $\\|\\cdot\\|:V^m\\to\\mathbb{R}$ — отображение с тремя аксиомами:\n- невырожденность: $\\|x\\|\\ge0$, $\\|x\\|=0\\iff x=\\bar0$;\n- однородность: $\\|\\alpha x\\|=|\\alpha|\\,\\|x\\|$;\n- неравенство треугольника: $\\|x+y\\|\\le\\|x\\|+\\|y\\|$.\n\n**Нормы Гёльдера** ($p\\ge1$):\n$$\\|x\\|_p=\\Bigl(\\sum_{j=1}^{m}|x_j|^{\\,p}\\Bigr)^{1/p}.$$\nРабочие случаи: $\\|x\\|_1=\\sum_j|x_j|$ (октаэдрическая), $\\|x\\|_2=\\sqrt{\\sum_j x_j^2}$ (евклидова), $\\|x\\|_\\infty=\\max_j|x_j|$ (кубическая). Единичные шары — ромб, круг, квадрат.\n\n**Матричная норма** добавляет к трём аксиомам четвёртую — *субмультипликативность* $\\|AB\\|\\le\\|A\\|\\,\\|B\\|$.\n\n## Центральный вывод: $\\|x\\|_\\infty=\\lim_{p\\to\\infty}\\|x\\|_p$\n\nПусть $x\\ne\\bar0$, $M=\\max_j|x_j|>0$. Вынесем $M$ из суммы:\n$$\\|x\\|_p=\\Bigl(\\sum_{j=1}^{m}M^{p}\\frac{|x_j|^{p}}{M^{p}}\\Bigr)^{1/p}=M\\Bigl(\\sum_{j=1}^{m}\\bigl(\\tfrac{|x_j|}{M}\\bigr)^{p}\\Bigr)^{1/p}.$$\nКаждое слагаемое лежит в $[0,1]$, а на $k\\ge1$ индексах, где $|x_j|=M$, оно равно $1$. Значит сумма зажата:\n$$k\\le\\sum_{j=1}^{m}\\bigl(\\tfrac{|x_j|}{M}\\bigr)^{p}\\le m.$$\nБеря корень степени $1/p$ и домножая на $M$:\n$$M\\,k^{1/p}\\le\\|x\\|_p\\le M\\,m^{1/p}.$$\nПри $p\\to\\infty$ имеем $k^{1/p}=e^{\\frac1p\\ln k}\\to1$ и $m^{1/p}\\to1$, поэтому по теореме о двух милиционерах\n$$\\lim_{p\\to\\infty}\\|x\\|_p=M=\\max_j|x_j|=\\|x\\|_\\infty.\\qquad\\blacksquare$$\n\n## Согласованность и подчинённость\n\nМатричная норма **согласована** с векторной, если $\\|Ax\\|\\le\\|A\\|\\,\\|x\\|$ для всех $x$. Норма **подчинённа** (операторная), если\n$$\\|A\\|=\\sup_{x\\ne0}\\frac{\\|Ax\\|}{\\|x\\|}=\\max_{\\|x\\|=1}\\|Ax\\|.$$\n**Подчинённость сильнее:** всякая подчинённая норма согласована (прямо по определению супремума $\\|Ax\\|\\le\\|A\\|\\,\\|x\\|$) и субмультипликативна, и для неё всегда $\\|E\\|=1$. Обратное неверно: норма может быть согласована, но не подчинена ни одной векторной (например, фробениусова норма согласована с $\\|\\cdot\\|_2$, но $\\|E\\|_F=\\sqrt{n}\\ne1$).\n\n**Вывод подчинённой $\\|A\\|_1$.** Из $\\|Ax\\|_1=\\sum_i|\\sum_j a_{ij}x_j|\\le\\sum_j|x_j|\\sum_i|a_{ij}|\\le(\\max_j\\sum_i|a_{ij}|)\\,\\|x\\|_1$ следует $\\|A\\|_1\\le\\max_j\\sum_i|a_{ij}|$. Равенство достигается на орте $x=e_{j_0}$ столбца-максимума, поэтому\n$$\\|A\\|_1=\\max_{j}\\sum_{i}|a_{ij}|\\quad(\\text{по столбцам}),\\qquad \\|A\\|_\\infty=\\max_{i}\\sum_{j}|a_{ij}|\\quad(\\text{по строкам}).$$\nДля $\\|A\\|_\\infty$ равенство достигается на векторе знаков $x_j=\\operatorname{sign}(a_{i_0 j})$. Подчинённая евклидовой норме $\\|A\\|_2=\\sigma_{\\max}(A)$.\n\n## Условия и применимость\n\n- Аксиомы гарантируют, что норма — *непрерывная* функция: $\\bigl|\\,\\|x\\|-\\|y\\|\\,\\bigr|\\le\\|x-y\\|$.\n- На конечномерном пространстве все нормы Гёльдера *эквивалентны*: $c\\|x\\|_q\\le\\|x\\|_p\\le C\\|x\\|_q$ — сходимость не зависит от выбора $p$.\n- Согласованность $\\|Ax\\|\\le\\|A\\|\\,\\|x\\|$ — рабочая лошадка всех априорных оценок погрешности (отсюда оценка через [[chislo-obuslovlennosti|число обусловленности]]).\n\nПодробный разбор и интерактивный код — [День 8](/aii/chma/4/day/8)."),
		examQ("Билет 10. Число обусловленности $\\mathrm{cond}(A)$ и относительная погрешность", "## Постановка задачи\n\nРешается невырожденная система $Ax=b$. На практике правая часть $b$ известна неточно: вместо неё задано $b+\\delta b$ (ошибки измерения, округления). Возмущение данных порождает возмущение решения: вместо $x$ получаем $x+\\delta x$. Спрашивается: **во сколько раз относительная ошибка решения $\\dfrac{\\|\\delta x\\|}{\\|x\\|}$ может превосходить относительную ошибку данных $\\dfrac{\\|\\delta b\\|}{\\|b\\|}$?** Этот коэффициент усиления и есть число обусловленности.\n\n## Определения и формулы\n\n[[chislo-obuslovlennosti|Число обусловленности]] невырожденной матрицы в подчинённой норме:\n$$\\mathrm{cond}(A)=\\|A\\|\\,\\|A^{-1}\\|.$$\n\nИспользуется свойство **согласованности** подчинённой нормы с векторной: для всех $x$\n$$\\|Ax\\|\\le\\|A\\|\\,\\|x\\|.$$\n\nПодчинённая норма по построению $\\|A\\|=\\sup_{x\\ne0}\\dfrac{\\|Ax\\|}{\\|x\\|}$ всегда согласована и субмультипликативна, причём $\\|E\\|=1$.\n\n## Центральный вывод оценки\n\nВычтем из возмущённой системы исходную. Поскольку $A(x+\\delta x)=b+\\delta b$ и $Ax=b$, то\n$$A\\,\\delta x=\\delta b\\quad\\Longrightarrow\\quad \\delta x=A^{-1}\\delta b.$$\n\n**Шаг 1.** Применим согласованную норму к $\\delta x=A^{-1}\\delta b$:\n$$\\|\\delta x\\|=\\|A^{-1}\\delta b\\|\\le\\|A^{-1}\\|\\,\\|\\delta b\\|. \\tag{1}$$\n\n**Шаг 2.** Применим её же к исходному $b=Ax$:\n$$\\|b\\|=\\|Ax\\|\\le\\|A\\|\\,\\|x\\|\\quad\\Longrightarrow\\quad \\frac{1}{\\|x\\|}\\le\\frac{\\|A\\|}{\\|b\\|}. \\tag{2}$$\n\n**Шаг 3.** Делим $\\|\\delta x\\|$ на $\\|x\\|$ и подставляем (1) и (2):\n$$\\frac{\\|\\delta x\\|}{\\|x\\|}\\le\\frac{\\|A^{-1}\\|\\,\\|\\delta b\\|}{\\|x\\|}\\le\\|A^{-1}\\|\\,\\|\\delta b\\|\\cdot\\frac{\\|A\\|}{\\|b\\|}=\\bigl(\\|A\\|\\,\\|A^{-1}\\|\\bigr)\\frac{\\|\\delta b\\|}{\\|b\\|}.$$\n\nВеличина в скобках — это $\\mathrm{cond}(A)$, откуда **основная оценка обусловленности**:\n$$\\boxed{\\;\\dfrac{\\|\\delta x\\|}{\\|x\\|}\\le\\mathrm{cond}(A)\\,\\dfrac{\\|\\delta b\\|}{\\|b\\|}.\\;}\\qquad\\blacksquare$$\n\nОтносительная ошибка решения не превосходит относительной ошибки данных, усиленной в $\\mathrm{cond}(A)$ раз. Оценка **строгая и достижимая** — на «худшем» $\\delta b$ (вдоль самого сжатого направления) она обращается в равенство.\n\n## Свойства, интерпретация, условия\n\n- **Снизу всегда $\\mathrm{cond}(A)\\ge1$.** По субмультипликативности на тождестве $AA^{-1}=E$: $1=\\|E\\|=\\|AA^{-1}\\|\\le\\|A\\|\\,\\|A^{-1}\\|=\\mathrm{cond}(A)$. Идеальный случай $\\mathrm{cond}=1$ дают кратные единичной и ортогональные матрицы (в спектральной норме).\n- **Инвариантность к масштабу:** $\\mathrm{cond}(\\alpha A)=\\mathrm{cond}(A)$, ведь $(\\alpha A)^{-1}=\\alpha^{-1}A^{-1}$.\n- **Спектральная норма:** $\\mathrm{cond}_2(A)=\\sigma_{\\max}/\\sigma_{\\min}$ — отношение старшего и младшего сингулярных чисел, то есть *вытянутость эллипсоида*, в который $A$ переводит единичный шар. Близость $A$ к вырожденной ($\\sigma_{\\min}\\to0$) раздувает $\\mathrm{cond}$.\n- **Потеря точности:** при $\\mathrm{cond}(A)\\sim10^{k}$ теряется около $k$ верных значащих цифр. Геометрически большое $\\mathrm{cond}$ — почти параллельные строки системы: точка пересечения «гуляет» от малейшего возмущения коэффициентов. При $\\mathrm{cond}\\gtrsim1/\\varepsilon_{\\text{маш}}\\approx10^{16}$ (double) результат любого прямого метода бессмыслен.\n- **Условие применимости:** $A$ невырождена ($\\det A\\ne0$), норма подчинённая (тогда согласованность выполнена автоматически).\n\nПодробный разбор и интерактивный код — [День 8](/aii/chma/4/day/8)."),
		examQ("Билет 11. Структура и сходимость итераций; оценка ошибки; метод Якоби", "## Постановка задачи\n\nДана система $Ax=b$ с невырожденной квадратной матрицей $A$ размера $m\\times m$ ($\\det A\\neq 0$, решение $x^{*}$ существует и единственно). Прямое решение стоит $O(m^{3})$; для больших разреженных систем выгоднее строить **итерационный процесс**, который последовательно приближает $x^{*}$. Требуется описать его структуру, выяснить условие сходимости и научиться оценивать ошибку приближения. Частный случай — [[metod-yakobi|метод Якоби]].\n\n## Ключевые определения и формулы\n\nСистему приводят к **эквивалентному виду** $x=Bx+c$ преобразованиями, не меняющими множество решений. Тогда $x^{*}=Bx^{*}+c$ — **неподвижная точка** отображения $x\\mapsto Bx+c$. Итерационный процесс:\n$$x^{k+1}=Bx^{k}+c,\\qquad k=0,1,2,\\dots$$\nс произвольным $x^{0}$. Процесс **сходится**, если $\\lim_{k\\to\\infty}\\lVert x^{*}-x^{k}\\rVert=0$ при любом $x^{0}$.\n\n**Критерий сходимости.** Процесс сходится тогда и только тогда, когда спектральный радиус $\\rho(B)=\\max_{j}\\lvert\\lambda_{j}(B)\\rvert<1$. **Достаточное условие** (удобное на практике): $\\lVert B\\rVert\\le q<1$ в какой-нибудь подчинённой [[norma-matricy|матричной норме]]; всегда $\\rho(B)\\le\\lVert B\\rVert$, поэтому импликация односторонняя.\n\n## Центральный вывод: убывание ошибки и оценка приближения\n\n**Шаг 1. Однородная рекурсия для ошибки.** Положим $e^{k}=x^{*}-x^{k}$. Вычтем $x^{k}=Bx^{k-1}+c$ из $x^{*}=Bx^{*}+c$ — вектор $c$ сокращается:\n$$e^{k}=(Bx^{*}+c)-(Bx^{k-1}+c)=B(x^{*}-x^{k-1})=B\\,e^{k-1}.$$\n\n**Шаг 2. Развёртывание до $x^{0}$:**\n$$e^{k}=B\\,e^{k-1}=B^{2}e^{k-2}=\\dots=B^{k}e^{0}.$$\n\n**Шаг 3. Переход к нормам.** По субмультипликативности $\\lVert B^{k}\\rVert\\le\\lVert B\\rVert^{k}$, поэтому при $\\lVert B\\rVert\\le q<1$\n$$\\lVert x^{*}-x^{k}\\rVert\\le q^{k}\\,\\lVert x^{*}-x^{0}\\rVert\\xrightarrow[k\\to\\infty]{}0,$$\nтак как $q^{k}\\to 0$ — априорная оценка, достаточность доказана.\n\n**Шаг 4. Апостериорная оценка.** Внутри множителя добавим и вычтем $x^{k}$:\n$$e^{k}=B\\big((x^{*}-x^{k})+(x^{k}-x^{k-1})\\big).$$\nПо неравенству треугольника $\\lVert x^{*}-x^{k}\\rVert\\le\\lVert B\\rVert\\,\\lVert x^{*}-x^{k}\\rVert+\\lVert B\\rVert\\,\\lVert x^{k}-x^{k-1}\\rVert$. Перенося первое слагаемое и деля на $1-\\lVert B\\rVert>0$:\n$$\\lVert x^{*}-x^{k}\\rVert\\le\\frac{\\lVert B\\rVert}{1-\\lVert B\\rVert}\\,\\lVert x^{k}-x^{k-1}\\rVert\\le\\frac{q}{1-q}\\,\\lVert x^{k}-x^{k-1}\\rVert.$$\nЭта формула оценивает расстояние до решения через *наблюдаемую* разность соседних приближений и служит критерием останова.\n\n## Сходимость метода Якоби\n\nРасщепляем $A=L+D+U$ ($D$ — диагональ, $L,U$ — строго ниже/выше неё). Оставив слева $Dx$: $Dx=-(L+U)x+b$, откуда\n$$x=-D^{-1}(L+U)x+D^{-1}b,\\qquad B_{J}=-D^{-1}(L+U).$$\nЭлементы $(B_{J})_{ij}=-a_{ij}/a_{ii}$ при $j\\neq i$ и $0$ при $j=i$. Строчная норма:\n$$\\lVert B_{J}\\rVert_{\\infty}=\\max_{i}\\frac{1}{\\lvert a_{ii}\\rvert}\\sum_{j\\neq i}\\lvert a_{ij}\\rvert.$$\nПри **строгом диагональном преобладании** $\\lvert a_{ii}\\rvert>\\sum_{j\\neq i}\\lvert a_{ij}\\rvert$ каждая дробь $<1$, значит $\\lVert B_{J}\\rVert_{\\infty}<1$, и по достаточному условию метод сходится. $\\blacksquare$\n\n## Условия, точность, область применимости\n\n- Сходимость линейная: ошибка убывает как геометрическая прогрессия, асимптотически $\\sim\\rho(B)^{k}$; чем меньше $\\rho(B)$, тем быстрее.\n- Достаточные условия ($\\lVert B\\rVert<1$, диагональное преобладание) **не необходимы** — окончательное слово за $\\rho(B)<1$.\n- Критерий останова по $\\lVert x^{k}-x^{k-1}\\rVert$ надёжен лишь при малом $q$: при $q\\to 1$ множитель $q/(1-q)$ велик, реальная ошибка может намного превышать наблюдаемую разность.\n- Перестановка строк часто создаёт диагональное преобладание — это законное эквивалентное преобразование.\n\nПодробный разбор и интерактивный код — [День 10](/aii/chma/4/day/10)."),
		examQ("Билет 12. Итерационные процессы, их сходимость и метод $\\text{Гаусса–Зейделя}$", "## Постановка задачи\n\nДана система $$Ax=b,$$ где $A$ — невырожденная квадратная матрица $m\\times m$, так что точное решение $x^{*}$ существует и единственно. Прямое обращение стоит $O(m^{3})$; вместо этого систему сводят к эквивалентной форме $x=Bx+c$ и приближают $x^{*}$ итерациями. Нужно описать **структуру** такого процесса, выяснить **условие сходимости**, дать **оценку ошибки** приближения и доказать **сходимость метода Гаусса–Зейделя**.\n\n## Ключевые определения и формулы\n\n**Эквивалентная система** — запись $x=Bx+c$, полученная из $Ax=b$ преобразованиями, не меняющими множество решений. Тогда $x^{*}=Bx^{*}+c$, то есть $x^{*}$ — *неподвижная точка* отображения $x\\mapsto Bx+c$. **Итерационный процесс**: $$x^{k+1}=Bx^{k}+c,\\qquad k=0,1,2,\\dots,$$ с произвольным $x^{0}$. Процесс *сходится*, если $\\lVert x^{*}-x^{k}\\rVert\\to 0$ при любом $x^{0}$.\n\n**Критерий сходимости.** Процесс сходится тогда и только тогда, когда $$\\rho(B)=\\max_{j}\\lvert\\lambda_{j}(B)\\rvert<1.$$ Достаточное (практичное) условие: $\\lVert B\\rVert\\le q<1$ в какой-нибудь подчинённой норме (всегда $\\rho(B)\\le\\lVert B\\rVert$).\n\n**Расщепление** $A=L+D+U$ ($D$ — диагональ, $L,U$ — строго ниже/выше). Гаусс–Зейдель включает уже вычисленную нижнюю часть слева: $(L+D)x^{k+1}=-Ux^{k}+b$, то есть $$B_{GS}=-(L+D)^{-1}U,\\qquad c_{GS}=(L+D)^{-1}b.$$\n\n## Центральный вывод\n\n**Убывание ошибки и апостериорная оценка.** Пусть $e^{k}=x^{*}-x^{k}$. Из $x^{*}=Bx^{*}+c$ и $x^{k}=Bx^{k-1}+c$ вычитанием (вектор $c$ сокращается): $$e^{k}=B(x^{*}-x^{k-1})=B\\,e^{k-1}=\\dots=B^{k}e^{0}.$$ Отсюда $\\lVert e^{k}\\rVert\\le q^{k}\\lVert e^{0}\\rVert\\to 0$. Подставляя $x^{*}-x^{k-1}=(x^{*}-x^{k})+(x^{k}-x^{k-1})$ и применяя неравенство треугольника: $$(1-\\lVert B\\rVert)\\lVert x^{*}-x^{k}\\rVert\\le\\lVert B\\rVert\\,\\lVert x^{k}-x^{k-1}\\rVert,$$ $$\\boxed{\\;\\lVert x^{*}-x^{k}\\rVert\\le\\frac{q}{1-q}\\lVert x^{k}-x^{k-1}\\rVert.\\;}$$\n\n**Сходимость Гаусса–Зейделя для СПД ($A=A^{T}>0$).** Тогда $U=L^{T}$, $A=L+D+L^{T}$. Ошибка $r^{k}=x^{*}-x^{k}$ удовлетворяет $r^{k+1}=(E-(L+D)^{-1}A)r^{k}$. Введём $v=(L+D)^{-1}Ar^{k}$, так что $Ar^{k}=(L+D)v$ и $r^{k+1}=r^{k}-v$. В энергетической норме $\\lVert x\\rVert_{A}^{2}=(Ax,x)$: $$\\lVert r^{k+1}\\rVert_{A}^{2}=(Ar^{k},r^{k})-2(Ar^{k},v)+(Av,v).$$ Подставляя $Ar^{k}=(L+D)v$ и $A=L+D+L^{T}$: $$\\lVert r^{k+1}\\rVert_{A}^{2}=\\lVert r^{k}\\rVert_{A}^{2}-\\big((L+D-L^{T})v,v\\big).$$ Кососимметричная часть даёт ноль, $((L-L^{T})v,v)=0$, остаётся диагональ: $$\\lVert r^{k+1}\\rVert_{A}^{2}=\\lVert r^{k}\\rVert_{A}^{2}-(Dv,v)\\le\\lVert r^{k}\\rVert_{A}^{2}-d\\,\\lVert v\\rVert_{2}^{2},\\quad d=\\min_i a_{ii}>0.$$ Так как $\\lVert r^{k}\\rVert_{A}^{2}\\le\\dfrac{\\lVert L+D\\rVert_{2}^{2}}{\\lambda_{\\min}}\\lVert v\\rVert_{2}^{2}$, получаем сжатие $$\\lVert r^{k+1}\\rVert_{A}^{2}\\le\\Big(1-d\\,\\frac{\\lambda_{\\min}}{\\lVert L+D\\rVert_{2}^{2}}\\Big)\\lVert r^{k}\\rVert_{A}^{2},\\qquad 0\\le 1-d\\,\\frac{\\lambda_{\\min}}{\\lVert L+D\\rVert_{2}^{2}}<1.$$ $A$-норма ошибки монотонно убывает геометрически, $\\lVert r^{k}\\rVert_{A}\\to 0$, значит $x^{k}\\to x^{*}$. $\\blacksquare$\n\n## Условия сходимости и применимость\n\n- $\\rho(B)<1$ — необходимо и достаточно; $\\lVert B\\rVert<1$ — лишь достаточно (из $\\rho(B)\\ge1$ берём собственный вектор $e^{0}=u^{(j)}$: $e^{k}=\\lambda_j^{k}u^{(j)}\\not\\to0$ — расходимость).\n- **Гаусс–Зейдель** гарантированно сходится для $A=A^{T}>0$ (доказано выше).\n- Скорость определяет $\\rho(B)$: ошибка падает $\\approx\\rho(B)^{k}$ за шаг; для СПД $\\rho(B_{GS})\\approx\\rho(B_{J})^{2}$.\n- Останов по $\\lVert x^{k}-x^{k-1}\\rVert<\\varepsilon$ надёжен лишь при малом $q$: множитель $\\tfrac{q}{1-q}$ велик при $q\\to1$.\n\nПодробный разбор и интерактивный код — [День 10](/aii/chma/4/day/10)."),
		examQ("Билет 13. Степенной метод: $\\lambda_{\\max}$, $\\lambda_{\\min}$, скорость и оценка ошибки", "## Постановка задачи\n\nДана симметричная матрица $A=A^{T}\\in\\mathbb{R}^{m\\times m}$. *Частичная* проблема собственных значений — найти не весь спектр, а лишь крайние собственные числа: наибольшее $\\lambda_1=\\lambda_{\\max}$ и наименьшее $\\lambda_m=\\lambda_{\\min}$ по модулю, вместе с их собственными векторами. Предполагаем строгое упорядочение по модулю\n$$|\\lambda_1|>|\\lambda_2|\\ge\\dots\\ge|\\lambda_{m-1}|>|\\lambda_m|>0,$$\nа собственные векторы $u^{(1)},\\dots,u^{(m)}$ для симметричной $A$ берём ортонормированными.\n\n## Ключевые определения и формулы\n\n[[stepennoj-metod|Степенной метод]] строит нормированную последовательность\n$$x^{k+1}=\\frac{Ax^k}{\\lVert Ax^k\\rVert},\\qquad x^0\\neq 0.$$\nСобственное число восстанавливается **отношением Рэлея**\n$$\\rho=\\frac{(Ax^k,x^k)}{(x^k,x^k)}\\xrightarrow[k\\to\\infty]{}\\lambda_1.$$\n\n## Центральный вывод сходимости\n\nРазложим старт по собственному базису ($c_1\\neq 0$):\n$$x^0=\\sum_{j=1}^{m}c_j u^{(j)}.$$\nТак как нормировка не меняет направления, оно совпадает с направлением $A^k x^0$. Применяя $Au^{(j)}=\\lambda_j u^{(j)}$ по индукции $k$ раз:\n$$x^k=\\frac{\\sum_{j}c_j\\lambda_j^{k}u^{(j)}}{\\bigl\\lVert\\sum_{j}c_j\\lambda_j^{k}u^{(j)}\\bigr\\rVert}=\\sum_{j=1}^{m}\\gamma_j\\lambda_j^{k}u^{(j)},$$\nгде $\\gamma_j$ — общий для всех слагаемых скаляр. Оценим угол $\\varphi$ между $x^k$ и $u^{(1)}$. Из ортонормированности в числителе $(x^k,u^{(1)})$ выживает только первый член:\n$$\\cos\\varphi=\\frac{|\\gamma_1\\lambda_1^{k}|}{\\bigl\\lVert\\sum_{j}\\gamma_j\\lambda_j^{k}u^{(j)}\\bigr\\rVert}.$$\nВынесем из-под нормы старший множитель $|\\lambda_1|^{k}$:\n$$\\Bigl\\lVert\\sum_{j}\\gamma_j\\lambda_j^{k}u^{(j)}\\Bigr\\rVert=|\\lambda_1|^{k}\\Bigl\\lVert\\gamma_1 u^{(1)}+\\sum_{j\\ge2}\\gamma_j\\Bigl(\\tfrac{\\lambda_j}{\\lambda_1}\\Bigr)^{k}u^{(j)}\\Bigr\\rVert.$$\nПоскольку $|\\lambda_j/\\lambda_1|<1$ при $j\\ge2$, хвост $\\to 0$ и норма стремится к $|\\lambda_1|^{k}|\\gamma_1|$. Отсюда $\\cos\\varphi\\to 1$, то есть $\\varphi\\to 0$ — $x^k$ выстраивается вдоль $u^{(1)}$. Подставив $x^k\\approx u^{(1)}$ в отношение Рэлея, получаем $\\rho\\to\\lambda_1$. $\\blacksquare$\n\n## Скорость и оценка ошибки\n\nДоминирующий хвостовой член $\\gamma_2(\\lambda_2/\\lambda_1)^{k}u^{(2)}$ задаёт скорость: длина проекции на дополнение к $u^{(1)}$ убывает как геометрическая прогрессия\n$$q=\\left|\\frac{\\lambda_2}{\\lambda_1}\\right|<1,\\qquad \\sin\\varphi\\sim q^{k}.$$\nДля **симметричной** $A$ ошибка отношения Рэлея квадратична по углу, поэтому\n$$|\\rho_k-\\lambda_1|=O\\!\\bigl(q^{2k}\\bigr),$$\nто есть в лог-шкале погрешность ложится прямой с наклоном $2\\ln q$. Чем сильнее $\\lambda_1$ отделён от спектра, тем быстрее сходимость; при $|\\lambda_2|\\to|\\lambda_1|$ имеем $q\\to 1$ и метод вырождается.\n\n## Минимальное по модулю и условия\n\n**Обратные итерации** — степенной метод для $A^{-1}$ (вместо умножения решают $Ay^{k+1}=x^k$). Собственные числа $A^{-1}$ суть $1/\\lambda_j$, старшее из них $1/\\lambda_{\\min}$, поэтому процесс сходится к $u^{(m)}$ со скоростью\n$$q_{\\min}=\\left|\\frac{\\lambda_{\\min}}{\\lambda_{m-1}}\\right|.$$\nСо сдвигом $A-\\sigma E$ итерации нацеливаются на ближайшее к $\\sigma$ собственное число.\n\n**Условия применимости:** строгое доминирование $|\\lambda_1|>|\\lambda_2|$ и $c_1\\neq 0$ (компонента старта вдоль $u^{(1)}$ ненулевая). При кратном или равном по модулю старшем собственном числе сходимость направления нарушается.\n\nПодробный разбор и интерактивный код — [День 11](/aii/chma/4/day/11)."),
		examQ("Билет 14. Метод плоских вращений Якоби; лемма об угле; норма Фробениуса", "## Постановка задачи\n\nДана **симметричная** матрица $A=A^{T}\\in\\mathbb{R}^{m\\times m}$. Требуется решить **полную** задачу собственных значений — найти весь спектр $\\lambda_1,\\dots,\\lambda_m$ и ортонормированный базис собственных векторов. [[vrashcheniya-yakobi|Метод вращений Якоби]] делает это цепочкой ортогональных подобий, обнуляющих по одному внедиагональному элементу, пока матрица не «сядет» на диагональ.\n\n## Определения и формулы\n\nИтерация ортогональных подобий:\n$$A_{k+1}=S_k^{T}A_k S_k,\\qquad A_0=A,\\qquad U_{k+1}=U_k S_k,\\ \\ U_0=E.$$\nЗдесь $S_k$ — **плоский поворот** в плоскости $(p,q)$: единичная матрица, у которой $s_{pp}=s_{qq}=\\cos\\varphi$, $s_{pq}=-\\sin\\varphi$, $s_{qp}=\\sin\\varphi$. Накопленная $U=\\prod_k S_k$ ортогональна и даёт собственные векторы.\n\n[[norma-frobeniusa|Норма Фробениуса]]: $\\lVert A\\rVert_{\\text{сф}}^2=\\sum_{i,j}a_{ij}^2=\\operatorname{Trace}(A^{T}A)$.\n\n## Лемма об угле и убывание внедиагонали (центральный вывод)\n\n**Шаг 1. Что меняет поворот.** Подобие $S_k^{T}A_kS_k$ затрагивает лишь строки и столбцы $p,q$; вне них элементы не меняются. Для затронутого элемента:\n$$a_{pq}^{(k+1)}=a_{pq}^{(k)}\\cos 2\\varphi+\\tfrac12\\bigl(a_{qq}^{(k)}-a_{pp}^{(k)}\\bigr)\\sin 2\\varphi.$$\n\n**Шаг 2. Условие обнуления (лемма об угле).** Приравняем $a_{pq}^{(k+1)}=0$:\n$$a_{pq}^{(k)}\\cos 2\\varphi+\\tfrac12\\bigl(a_{qq}^{(k)}-a_{pp}^{(k)}\\bigr)\\sin 2\\varphi=0\\ \\Longrightarrow\\ \\tan 2\\varphi=\\frac{2a_{pq}^{(k)}}{a_{pp}^{(k)}-a_{qq}^{(k)}}=t.$$\nОтсюда через формулы половинного угла (знак — для наименьшего поворота):\n$$\\cos\\varphi=\\sqrt{\\tfrac12\\Bigl(1+\\tfrac{1}{\\sqrt{1+t^2}}\\Bigr)},\\quad \\sin\\varphi=\\operatorname{sign}(t)\\sqrt{\\tfrac12\\Bigl(1-\\tfrac{1}{\\sqrt{1+t^2}}\\Bigr)}.$$\nСимметрия сохраняется: $a_{pq}^{(k+1)}=a_{qp}^{(k+1)}=0$ — *симметричные элементы обращаются в ноль одновременно*.\n\n**Шаг 3. Инвариантность нормы Фробениуса.** Для ортогональной $S$ ($S^{T}S=SS^{T}=E$), используя $\\operatorname{Trace}(XY)=\\operatorname{Trace}(YX)$:\n$$\\lVert S^{T}AS\\rVert_{\\text{сф}}^2=\\operatorname{Trace}\\bigl(S^{T}A^{T}SS^{T}AS\\bigr)=\\operatorname{Trace}\\bigl(S^{T}A^{T}AS\\bigr)=\\operatorname{Trace}\\bigl(A^{T}A\\,SS^{T}\\bigr)=\\lVert A\\rVert_{\\text{сф}}^2.$$\nПолная сумма квадратов всех элементов фиксирована на всех итерациях.\n\n**Шаг 4. Локальный баланс.** Прямой подсчёт даёт сохранение блоковых сумм: для $j\\neq p,q$ выполнено $(a_{pj}^{(k+1)})^2+(a_{qj}^{(k+1)})^2=(a_{pj}^{(k)})^2+(a_{qj}^{(k)})^2$, а для блока $2\\times2$ — $(a_{pp}^{(k+1)})^2+(a_{qq}^{(k+1)})^2+2(a_{pq}^{(k+1)})^2=(a_{pp}^{(k)})^2+(a_{qq}^{(k)})^2+2(a_{pq}^{(k)})^2$.\n\n**Шаг 5. Внедиагональ убывает.** Пусть $\\operatorname{off}(A)^2=\\sum_{i\\neq j}a_{ij}^2$. После обнуления диагональные квадраты выросли ровно на $2(a_{pq}^{(k)})^2$, а полная норма (шаг 3) и внедиагональ вне пары $(p,q)$ (шаг 4) неизменны, поэтому\n$$\\operatorname{off}(A_{k+1})^2=\\operatorname{off}(A_k)^2-2\\bigl(a_{pq}^{(k)}\\bigr)^2.$$\n\n## Сходимость, условия, применимость\n\nВыбирая на каждом шаге **наибольший по модулю** внедиагональный элемент (классический Якоби), имеем $2(a_{pq}^{(k)})^2\\ge\\frac{2}{m(m-1)}\\operatorname{off}(A_k)^2$, откуда\n$$\\operatorname{off}(A_{k+1})^2\\le\\Bigl(1-\\tfrac{2}{m(m-1)}\\Bigr)\\operatorname{off}(A_k)^2\\xrightarrow[k\\to\\infty]{}0.$$\nЗначит $A_k\\to D=\\operatorname{diag}(d_1,\\dots,d_m)$, причём $D=U^{T}AU$: из $De^{(j)}=d_je^{(j)}$ следует $A(Ue^{(j)})=d_j(Ue^{(j)})$, то есть $d_j=\\lambda_j$, а столбцы $U$ — собственные векторы. $\\blacksquare$\n\n**Условия и применимость.** Метод работает только для **симметричной** $A$ (тогда спектр действителен, а подобия сохраняют симметрию). Сходимость глобальная: ранее обнулённые элементы могут слегка «ожить» от последующих поворотов, но баланс постоянной массы Фробениуса гарантирует общее убывание $\\operatorname{off}$ до нуля. Якоби незаменим, когда нужна высокая *относительная* точность малых собственных чисел.\n\nПодробный разбор и интерактивный код — [День 11](/aii/chma/4/day/11)."),
		examQ("Билет 15. Структура [[svd|SVD]], сингулярные числа, алгоритмы построения", "## Постановка задачи\n\nДана прямоугольная матрица $A\\in\\mathbb{R}^{n\\times m}$. Требуется описать её **сингулярное разложение** ([[svd|SVD]]): структуру множителей $U,\\Sigma,V$, определить сингулярные числа $\\sigma_i$ и доказать, что они суть корни из собственных чисел $A^{T}A$ — это и даёт конструктивный алгоритм построения разложения.\n\n## Ключевые определения\n\nСингулярным разложением называется представление\n$$A_{n,m}=U_{n,n}\\,\\Sigma_{n,m}\\,V^{T}_{m,m},$$\nгде $U$ ортогональна (столбцы — **левые** сингулярные векторы $u^{(i)}$), $V$ ортогональна (столбцы — **правые** векторы $v^{(j)}$), а $\\Sigma$ — прямоугольная диагональная с **сингулярными числами** $\\sigma_1\\ge\\sigma_2\\ge\\dots\\ge\\sigma_r>0$ на диагонали ($r=\\operatorname{rank}A$, остальные нули). Эквивалентная **диадная (скелетная) форма** — сумма матриц ранга 1:\n$$A=\\sum_{j=1}^{r}\\sigma_j\\,u^{(j)}v^{(j)T}.$$\nРазложение неединственно: в нуль-пространствах ($n>r$ для $U$, $m>r$ для $V$) векторы выбираются произвольно с сохранением ортонормированности.\n\n## Центральный вывод: $\\sigma_j=\\sqrt{\\lambda_j}$ и алгоритм построения\n\nПодставим $A=U\\Sigma V^{T}$ в $A^{T}A$ и используем $U^{T}U=E$:\n$$A^{T}A=(U\\Sigma V^{T})^{T}(U\\Sigma V^{T})=V\\,\\Sigma^{T}U^{T}U\\Sigma\\,V^{T}=V\\,(\\Sigma^{T}\\Sigma)\\,V^{T}.$$\nМатрица $\\Sigma^{T}\\Sigma=\\operatorname{diag}(\\sigma_1^2,\\dots,\\sigma_r^2,0,\\dots)$ диагональна, $V$ ортогональна — значит это **спектральное разложение** симметричной неотрицательно определённой матрицы $A^{T}A$. Следовательно её собственные числа $\\lambda_j=\\sigma_j^2$, а собственные векторы — столбцы $V$:\n$$A^{T}A\\,v^{(j)}=\\sigma_j^2\\,v^{(j)}\\;\\Longrightarrow\\;\\sigma_j=\\sqrt{\\lambda_j}\\ge0.$$\nСимметрично $AA^{T}=U(\\Sigma\\Sigma^{T})U^{T}$ даёт левые векторы $u^{(j)}$ с тем же ненулевым спектром. Связь множителей: умножив $A^{T}A\\,v^{(j)}=\\sigma_j^2 v^{(j)}$ слева на $A$, получаем $AA^{T}(Av^{(j)})=\\sigma_j^2(Av^{(j)})$, откуда\n$$u^{(j)}=\\frac{1}{\\sigma_j}\\,A\\,v^{(j)},\\qquad A\\,v^{(j)}=\\sigma_j\\,u^{(j)}.$$\n\nЭто и есть **алгоритм построения SVD** через спектральную задачу:\n- собрать симметричную $A^{T}A$ (размер $m\\times m$);\n- диагонализовать её, найти $\\lambda_j\\ge0$ и ортонормированные $v^{(j)}$ (упорядочить $\\lambda_1\\ge\\dots\\ge\\lambda_r>0$);\n- положить $\\sigma_j=\\sqrt{\\lambda_j}$, $V=[v^{(1)},\\dots]$;\n- восстановить левые векторы $u^{(j)}=Av^{(j)}/\\sigma_j$ **без** отдельной диагонализации $AA^{T}$; при $n>r$ дополнить $U$ до ортонормированного базиса.\n\nСпектральную задачу для симметричной $A^{T}A$ можно решать вращениями — отсюда связь с [[metod-yakobi|методом вращений Якоби]].\n\n## Свойства, точность, область применимости\n\nИз структуры сразу следуют ключевые факты. Спектральная [[norma-matricy|норма]] равна старшему числу $\\|A\\|_2=\\sigma_1$, а $\\|A^{-1}\\|_2=1/\\sigma_r$, откуда [[chislo-obuslovlennosti|число обусловленности]]\n$$\\operatorname{cond}_2(A)=\\frac{\\sigma_{\\max}}{\\sigma_{\\min}}=\\frac{\\sigma_1}{\\sigma_r}.$$\nПо теореме **Эккарт–Янга** усечение диадной суммы даёт наилучшее приближение ранга $\\le k$ с точной ошибкой $\\sigma_{k+1}$. Псевдообратная $A^{+}=\\sum_j \\sigma_j^{-1}v^{(j)}u^{(j)T}$ решает [[mnk|МНК]]-задачу $x=A^{+}b$.\n\n**Замечание о точности алгоритма.** Сборка через $A^{T}A$ возводит обусловленность в квадрат ($\\operatorname{cond}_2(A^{T}A)=\\operatorname{cond}_2(A)^2$), теряя малые $\\sigma_j$ при близком к вырожденности $A$; численно устойчивее прямые методы (бидиагонализация + QR-итерации). Геометрически SVD — это поворот $V^{T}$, растяжение по осям $\\sigma_j$ и доворот $U$: образ сферы — эллипсоид с полуосями $\\sigma_j$ вдоль $u^{(j)}$.\n\nПодробный разбор и интерактивный код — [День 9](/aii/chma/4/day/9)."),
		examQ("Билет 16. Отделение корней; деление пополам, секущие, скорость сходимости", "## Постановка задачи\n\nДана непрерывная нелинейная функция $f:\\mathbb{R}\\to\\mathbb{R}$. Требуется найти **корень** $x^*$ уравнения\n$$f(x^*)=0.$$\nЯвной формулы для $x^*$, как правило, нет, поэтому корень ищут *итерационно*: строят последовательность $x_0,x_1,x_2,\\dots\\to x^*$. Перед итерациями корень нужно **отделить (локализовать)**, а в процессе — контролировать ошибку $\\varepsilon_k=|x^*-x_k|$ до заданной точности $\\bar\\varepsilon$.\n\n## Определения и формулы\n\n**Отделение корня.** Корень локализован на $[a;b]$, если он там существует и единственен. Достаточное условие (теорема Больцано–Коши): если $f$ непрерывна на $[a;b]$ и концевые знаки разные,\n$$f(a)\\,f(b)<0,$$\nто внутри есть корень; если вдобавок $f$ строго монотонна ($f'$ не меняет знак), корень единствен. Практически считают $f$ на сетке узлов и берут соседние точки с разными знаками.\n\n**Критерий остановки.** Для отрезочных методов $x^*,\\tilde x\\in[a;b]$, поэтому $\\varepsilon\\le b-a$ — достаточно довести длину до $b-a\\le\\bar\\varepsilon$ (апостериорная оценка).\n\n**Метод половинного деления.** Пусть $f(a)f(b)<0$. Берём середину $c=\\tfrac{a+b}{2}$ и сужаем: если $\\operatorname{sign}f(a)=\\operatorname{sign}f(c)$, полагаем $a:=c$, иначе $b:=c$. За шаг длина делится пополам, корень заперт внутри. Метод [[metod-deleniya|деления отрезка пополам]] сходится **всегда**, но *линейно*: $\\varepsilon_{k+1}\\le\\tfrac12\\varepsilon_k$.\n\n**Метод секущих.** Заменяем $f$ на $[x_{k-1};x_k]$ её линейным интерполянтом ([[polinom-lagranzha|полином Лагранжа]] первой степени) и берём нуль секущей:\n$$x_{k+1}=x_k-\\frac{f(x_k)\\,(x_k-x_{k-1})}{f(x_k)-f(x_{k-1})}.$$\nПроизводная не нужна, но требуются две стартовые точки. Метод [[metod-sekushchih|секущих]] даёт абсциссу пересечения с $Ox$ прямой через $(x_{k-1},f(x_{k-1}))$ и $(x_k,f(x_k))$.\n\n## Центральный вывод: порядок сходимости секущих\n\nДля секущих остаток линейной интерполяции в точке $x^*$ ($f(x^*)=0$, $x_{k+1}$ — корень $Q_1$) даёт\n$$\\varepsilon_{k+1}\\approx M\\,\\varepsilon_k\\,\\varepsilon_{k-1},\\qquad M=\\left|\\frac{f''(x^*)}{2f'(x^*)}\\right|.$$\nИщем порядок $p$ из анзаца $|\\varepsilon_{k+1}|\\approx K|\\varepsilon_k|^p$. Тогда $|\\varepsilon_k|\\approx K|\\varepsilon_{k-1}|^p$, откуда\n$$|\\varepsilon_{k-1}|\\approx K^{-1/p}|\\varepsilon_k|^{1/p}.$$\nПодставляем обе асимптотики в $|\\varepsilon_{k+1}|\\approx M|\\varepsilon_k||\\varepsilon_{k-1}|$:\n$$K|\\varepsilon_k|^p\\approx M\\,|\\varepsilon_k|\\cdot K^{-1/p}|\\varepsilon_k|^{1/p}=MK^{-1/p}\\,|\\varepsilon_k|^{\\,1+1/p}.$$\nРавенство при всех малых $|\\varepsilon_k|$ требует совпадения показателей:\n$$p=1+\\frac1p\\ \\Longleftrightarrow\\ p^2-p-1=0.$$\nПоложительный корень — **золотое сечение**:\n$$p=\\frac{1+\\sqrt5}{2}\\approx1{,}618.$$\nСходимость *сверхлинейная*: быстрее деления ($p=1$), медленнее Ньютона ($p=2$), но без вычисления $f'$. $\\blacksquare$\n\n## Ошибки, условия и область применимости\n\n- **Деление пополам:** сходится при единственном требовании $f(a)f(b)<0$; абсолютно надёжно (использует только знак $f$), но медленно — один десятичный знак за $\\log_2 10\\approx3{,}3$ шага.\n- **Секущие:** сверхлинейны ($p\\approx1{,}618$), но сходимость *локальна* — гарантирована лишь вблизи корня и при $f'(x^*)\\ne0$ (нет кратного корня) и ограниченной $f''$; при дальнем старте или $f'\\approx0$ возможна расходимость.\n- **Стоимость шага:** секущие требуют *одного* нового вычисления $f$ за шаг (Ньютон — двух: $f$ и $f'$), поэтому по числу вычислений $f$ часто конкурентоспособны.\n- **Практический гибрид:** сначала несколько шагов деления для надёжной локализации, затем секущие/Ньютон для быстрого добивания до $\\bar\\varepsilon$.\n\nПодробный разбор и интерактивный код — [День 7](/aii/chma/4/day/7)."),
		examQ("Билет 17. Метод Ньютона для систем нелинейных уравнений", "## Постановка задачи\n\nДана система $m$ нелинейных уравнений с $m$ неизвестными. Требуется найти вектор $\\mathbf{x}^*$ такой, что\n$$\\mathbf{f}(\\mathbf{x}^*)=\\bar0,\\qquad \\mathbf{x}=\\begin{bmatrix}x_1\\\\\\vdots\\\\x_m\\end{bmatrix},\\quad \\mathbf{f}(\\mathbf{x})=\\begin{bmatrix}f_1(x_1,\\dots,x_m)\\\\\\vdots\\\\f_m(x_1,\\dots,x_m)\\end{bmatrix}.$$\nЯвной формулы для $\\mathbf{x}^*$ нет, поэтому строят итерационную последовательность $\\mathbf{x}_0,\\mathbf{x}_1,\\dots\\to\\mathbf{x}^*$, линеаризуя $\\mathbf{f}$ в текущей точке.\n\n## Ключевые определения\n\nРоль производной играет матрица [[yakobian|Якоби]] — [[yakobian|якобиан]]:\n$$J(\\mathbf{x})=\\mathbf{f}'(\\mathbf{x})=\\begin{bmatrix}\\dfrac{\\partial f_1}{\\partial x_1}&\\cdots&\\dfrac{\\partial f_1}{\\partial x_m}\\\\\\vdots&\\ddots&\\vdots\\\\\\dfrac{\\partial f_m}{\\partial x_1}&\\cdots&\\dfrac{\\partial f_m}{\\partial x_m}\\end{bmatrix}.$$\n\n## Центральный вывод рабочих формул\n\n**Шаг 1. Многомерный ряд Тейлора.** Пусть $\\mathbf{x}^*=\\mathbf{x}+\\boldsymbol\\varepsilon$, где $\\boldsymbol\\varepsilon$ — векторная ошибка. Разложение первого порядка:\n$$\\mathbf{f}(\\mathbf{x}^*)=\\mathbf{f}(\\mathbf{x}+\\boldsymbol\\varepsilon)=\\mathbf{f}(\\mathbf{x})+J(\\mathbf{x})\\,\\boldsymbol\\varepsilon+O(\\|\\boldsymbol\\varepsilon\\|^2)=\\bar0.$$\n\n**Шаг 2. Линеаризация.** Отбрасываем $O(\\|\\boldsymbol\\varepsilon\\|^2)$ и подставляем $\\boldsymbol\\varepsilon=\\mathbf{x}^*-\\mathbf{x}$:\n$$\\mathbf{f}(\\mathbf{x})+J(\\mathbf{x})\\,(\\mathbf{x}^*-\\mathbf{x})\\approx\\bar0\\ \\Rightarrow\\ \\mathbf{x}^*\\approx\\mathbf{x}-[J(\\mathbf{x})]^{-1}\\mathbf{f}(\\mathbf{x}).$$\nОтсюда **итерационный процесс Ньютона для систем**:\n$$\\mathbf{x}_{k+1}=\\mathbf{x}_k-[J(\\mathbf{x}_k)]^{-1}\\mathbf{f}(\\mathbf{x}_k).\\qquad(1.50)$$\n\n**Рабочая форма (ключевая для практики).** Матрицу *не обращают*, а решают линейную СЛАУ относительно поправки $\\Delta\\mathbf{x}_k=\\mathbf{x}_{k+1}-\\mathbf{x}_k$:\n$$J(\\mathbf{x}_k)\\,\\Delta\\mathbf{x}_k=-\\mathbf{f}(\\mathbf{x}_k),\\qquad \\mathbf{x}_{k+1}=\\mathbf{x}_k+\\Delta\\mathbf{x}_k.$$\nЭто дешевле и устойчивее явного $J^{-1}$ — одно решение СЛАУ [[metod-gaussa-zejdelya|прямыми методами]] за шаг.\n\n**Второй вывод (через параметризацию).** Положим $\\mathbf{g}(t)=\\mathbf{f}(\\mathbf{x}+t\\boldsymbol\\varepsilon)$. Тогда точно\n$$\\int_0^1\\frac{d\\,\\mathbf{f}(\\mathbf{x}+t\\boldsymbol\\varepsilon)}{dt}\\,dt=\\mathbf{f}(\\mathbf{x}+\\boldsymbol\\varepsilon)-\\mathbf{f}(\\mathbf{x})=-\\mathbf{f}(\\mathbf{x}),$$\nпоскольку $\\mathbf{f}(\\mathbf{x}^*)=\\bar0$. Приближая интеграл [[kvadraturnaya-formula|формулой прямоугольников]] (левый узел, длина $1$):\n$$\\int_0^1 J(\\mathbf{x}+t\\boldsymbol\\varepsilon)\\,\\boldsymbol\\varepsilon\\,dt\\approx J(\\mathbf{x})\\,(\\mathbf{x}^*-\\mathbf{x}),$$\nсравнивая, снова получаем $\\mathbf{x}^*\\approx\\mathbf{x}-[J(\\mathbf{x})]^{-1}\\mathbf{f}(\\mathbf{x})$ — ту же структуру (1.50). $\\blacksquare$\n\n## Область сходимости и применение\n\nСкалярные условия обобщаются: вместо $|1/f'|$ работает [[norma-matricy|норма]] $\\|J^{-1}\\|$, вместо $|f''|$ — оценка вторых производных компонент. **Метод (1.50) сходится квадратично**, если:\n- якобиан $J(\\mathbf{x}^*)$ *невырожден* ($\\det J\\ne0$ — аналог отсутствия кратного корня),\n- $\\mathbf{f}$ дважды непрерывно дифференцируема,\n- старт $\\mathbf{x}_0$ достаточно близок к $\\mathbf{x}^*$ (близость в [[norma-vektora|векторной норме]]).\n\nЭто содержание **теоремы Канторовича** в многомерной форме. Большое [[chislo-obuslovlennosti|число обусловленности]] $\\operatorname{cond}(J)$ делает поправку $\\Delta\\mathbf{x}$ ненадёжной — сходимость ухудшается. Сходимость *локальна*: издалека итерации могут «улететь».\n\n**Применение.** (1) Системы уравнений в физике, химии, механике. (2) Если $\\mathbf{f}=\\nabla F$, то Ньютон для $\\nabla F=\\bar0$ — это метод Ньютона *оптимизации*, где $J$ становится матрицей Гессе; нахождение корней переходит в безусловную минимизацию. **Протокол:** локализовать область, при необходимости огрубить старт, затем Ньютон до контроля $\\|\\mathbf{f}(\\mathbf{x}_k)\\|<\\bar\\varepsilon$ и $\\|\\Delta\\mathbf{x}_k\\|<\\bar\\varepsilon$ одновременно.\n\nПодробный разбор и интерактивный код — [День 7](/aii/chma/4/day/7).")
	],
	tasks: [],
	mastery: []
};

